css:
.hero{position:relative; overflow:hidden; height:min(88vh,720px)}
.hero>img{width:100%; height:100%; object-fit:cover}
.panel{position:absolute; top:0; right:0; width:39%; height:100%;
  background:#c8a44e; z-index:3;
  display:flex; flex-direction:column; align-items:center; text-align:center;
  gap:18px; padding:32px 24px}
@media(max-width:768px){
  .hero{height:auto}
  .panel{position:static; width:100%; height:auto}
}
